urlset:
    {% spaceless %}
{% for url in urlset %}

    {{ url.location }}
    {% if url.lastmod %}{{ url.lastmod|date:"Y-m-d" }}{% endif %}
    {% if url.changefreq %}{{ url.changefreq }}{% endif %}
    {% if url.priority %}{{ url.priority }}{% endif %}
    {% if url.item.data %}

            {{ request.scheme }}://{{ request.get_host }}{{ url.item.data.url }}

    {% endif %}

{% endfor %}
{% endspaceless %}
